const NOW = "2026-01-02T10:00:00.000Z", CASE = "fixture-case-coordination", OWNER = "fixture-worker-01"
const decision = () => ({ caseImportId:CASE, caseFingerprint:"abcdef123456", caseNumber:"PRV.260102.001", authorizablePlanHash:"a".repeat(64), authorizationIds:["fixture-auth-apply","fixture-auth-writes"] })
