  const releaseLocks=(id,held)=>{for(const key of held){const current=locks.get(key);if(!current||current.owner!==id)continue;const next=current.waiters.shift();if(next){current.owner=next.id;queueMicrotask(next.resolve)}else locks.delete(key)}held.clear()}
