// Primary key and unique constraint tests
test("PK errada é rejeitada",async()=>{const pool=memoryPool();pool.state.schema=true;const base=pool.query;pool.query=async(sql,p)=>{const result=await base(sql,p);if(String(sql).includes("FROM pg_constraint")&&p[0]===CHECKPOINT_TABLE){result.rows=result.rows.map(r=>r.contype==='p'?{...r,columns:JSON.stringify(["wrong_pk"])}:r)}return result};const res=await validateSingleCaseCoordinationSchema(pool);assert.equal(res.ok,false);assert(res.codes.some(c=>c.includes("PRIMARY_KEY_MISMATCH")))})

test("unique constraint com colunas erradas é rejeitada",async()=>{const pool=memoryPool();pool.state.schema=true;const base=pool.query;pool.query=async(sql,p)=>{const result=await base(sql,p);if(String(sql).includes("FROM pg_constraint")&&p[0]===LEASE_TABLE){result.rows=result.rows.map(r=>r.contype==='u'?{...r,columns:JSON.stringify(["wrong_col"])}:r)}return result};const res=await validateSingleCaseCoordinationSchema(pool);assert.equal(res.ok,false);assert(res.codes.some(c=>c.includes("UNIQUE_MISMATCH")))})

test("unique constraint em JSON-string válida aceita quando correta",async()=>{const pool=memoryPool();pool.state.schema=true;const base=pool.query;pool.query=async(sql,p)=>{const result=await base(sql,p);if(String(sql).includes("FROM pg_constraint")&&p[0]===LEASE_TABLE){result.rows=result.rows.map(r=>r.contype==='u'?{...r,columns:JSON.stringify(r.columns)}:r)}return result};const res=await validateSingleCaseCoordinationSchema(pool);assert.equal(res.ok,true)})

test("índice com colunas em ordem errada é rejeitado",async()=>{const pool=memoryPool();pool.state.schema=true;const base=pool.query;pool.query=async(sql,p)=>{const result=await base(sql,p);if(String(sql).includes("FROM pg_index")){result.rows=result.rows.map(r=>({...r,key_columns:JSON.stringify(["other","expires_at"]) }))}return result};const res=await validateSingleCaseCoordinationSchema(pool);assert.equal(res.ok,false);assert(res.codes.includes("LEASE_EXPIRY_INDEX_MISMATCH"))})

test("CHECK com colunas erradas é rejeitada",async()=>{const pool=memoryPool();pool.state.schema=true;const base=pool.query;pool.query=async(sql,p)=>{const result=await base(sql,p);if(String(sql).includes("FROM pg_constraint")&&p[0]===LEASE_TABLE)result.rows=result.rows.map(r=>r.contype==='c'&&r.conname.includes("lease_token")?{...r,columns:JSON.stringify(["wrong"])}:r);return result};const res=await validateSingleCaseCoordinationSchema(pool);assert.equal(res.ok,false);assert(res.codes.some(c=>c.includes("CHECK_MISMATCH")))})

// Regression tests for PostgreSQL 18 NOT NULL constraints (contype = "n")
