test("foreign key inesperada continua produzindo UNEXPECTED_CONSTRAINT",async()=>{const pool=memoryPool();pool.state.schema=true;const base=pool.query;pool.query=async(sql,p)=>{const result=await base(sql,p);if(String(sql).includes("FROM pg_constraint")&&p[0]===LEASE_TABLE){result.rows.push({conname:"unexpected_fk",contype:"f",definition:"FOREIGN KEY (case_import_id) REFERENCES other_table(id)",columns:["case_import_id"]})}return result};const res=await validateSingleCaseCoordinationSchema(pool);assert.equal(res.ok,false);assert(res.codes.some(c=>c.includes("UNEXPECTED_CONSTRAINT")))})

