test("migração registra somente após validação e é idempotente",async()=>{const pool=memoryPool();assert.equal((await migrateSingleCaseCoordination(pool)).applied,true);assert.equal((await migrateSingleCaseCoordination(pool)).applied,false);assert.equal(pool.state.migrated,true);assert.equal(pool.state.lease,null);assert.equal(pool.state.checkpoint,null)})
test("divergência de schema causa rollback",async()=>{const pool=memoryPool();pool.state.migrated=true;await assert.rejects(()=>migrateSingleCaseCoordination(pool),/SCHEMA_INCOMPATIBLE/);assert.equal(pool.state.rollbacks,1)})
test("composition exige dependências explícitas e não conecta",()=>{const pool=memoryPool();const components=createSingleCaseCoordinationComponents({pool,clock:()=>NOW,ownerId:OWNER,leaseDurationMs:60000});assert(components.coordination);assert.equal(pool.state.writes,0)})
test("CLI permanece fora da composição",()=>{const source=require("node:fs").readFileSync(require.resolve("../src/composition/single-case-coordination-components"),"utf8");assert(!source.includes("apply-single-case"));assert(!source.includes("dotenv"))})

test("sanitização não aceita POSTGRES_ com host e porta",()=>{const source=new Error("POSTGRES_UNAVAILABLE host=db.internal port=5432 token=fake-secret"),mapped=mapError(source);assert.equal(mapped.message,"POSTGRES_TRANSACTION_FAILED");assert(!mapped.message.includes("host"));assert(!mapped.message.includes("port"));assert(!mapped.message.includes("token"))})
test("sanitização não aceita POSTGRES_TRANSACTION_FAILED com SQL",()=>{const source=new Error("POSTGRES_TRANSACTION_FAILED SQL=SELECT * FROM clientes WHERE cpf='00000000000'"),mapped=mapError(source);assert.equal(mapped.message,"POSTGRES_TRANSACTION_FAILED");assert(!mapped.message.includes("SQL"));assert(!mapped.message.includes("SELECT"));assert(!mapped.message.includes("clientes"));assert(!mapped.message.includes("00000000000"))})
test("sanitização não aceita LEASE_OWNER_MISMATCH com pessoa fictícia",()=>{const source=new Error("LEASE_OWNER_MISMATCH owner=Pessoa Fictícia token=fake-secret"),mapped=mapError(source);assert.equal(mapped.message,"POSTGRES_TRANSACTION_FAILED");assert(!mapped.message.includes("owner"));assert(!mapped.message.includes("Pessoa"));assert(!mapped.message.includes("token"))})
test("sanitização não aceita CHECKPOINT_BINDING_MISMATCH com JSON",()=>{const source=new Error('CHECKPOINT_BINDING_MISMATCH checkpoint={"cpf":"00000000000","phone":"11999999999"}'),mapped=mapError(source);assert.equal(mapped.message,"POSTGRES_TRANSACTION_FAILED");assert(!mapped.message.includes("checkpoint"));assert(!mapped.message.includes("cpf"));assert(!mapped.message.includes("00000000000"))})
test("sanitização não aceita SCHEMA_INCOMPATIBLE com comando DDL",()=>{const source=new Error("SCHEMA_INCOMPATIBLE DROP TABLE clientes"),mapped=mapError(source);assert.equal(mapped.message,"POSTGRES_TRANSACTION_FAILED");assert(!mapped.message.includes("DROP"));assert(!mapped.message.includes("TABLE"));assert(!mapped.message.includes("clientes"))})
test("sanitização não aceita LEASE_EXPIRED com sufixo arbitrário",()=>{const source=new Error("LEASE_EXPIRED extra_content"),mapped=mapError(source);assert.equal(mapped.message,"POSTGRES_TRANSACTION_FAILED");assert(!mapped.message.includes("extra"))})
test("sanitização não aceita LEASE_EXPIRED com dois-pontos e sufixo",()=>{const source=new Error("LEASE_EXPIRED: segredo"),mapped=mapError(source);assert.equal(mapped.message,"POSTGRES_TRANSACTION_FAILED");assert(!mapped.message.includes("segredo"))})
test("sanitização não aceita LEASE_EXPIRED com quebra de linha",()=>{const source=new Error("LEASE_EXPIRED\nsegredo-oculto"),mapped=mapError(source);assert.equal(mapped.message,"POSTGRES_TRANSACTION_FAILED");assert(!mapped.message.includes("segredo"));assert(!mapped.message.includes("\n"))})
test("sanitização não aceita prefixo antes do código interno",()=>{const source=new Error("prefixo_LEASE_EXPIRED"),mapped=mapError(source);assert.equal(mapped.message,"POSTGRES_TRANSACTION_FAILED");assert(!mapped.message.includes("prefixo"))})
test("sanitização não aceita FENCING_REJECTED com texto longo e PII",()=>{const source=new Error("FENCING_REJECTED secret-token-abc123def456 " + "x".repeat(100) + " CPF:00000000000 PHONE:11999999999"),mapped=mapError(source);assert.equal(mapped.message,"POSTGRES_TRANSACTION_FAILED");assert(!mapped.message.includes("secret"));assert(!mapped.message.includes("token"));assert(!mapped.message.includes("00000000000"));assert(!mapped.message.includes("11999999999"))})
test("sanitização não aceita INVALID_CHECKPOINT com checkpoint_payload",()=>{const source=new Error("INVALID_CHECKPOINT checkpoint_payload={\"version\":123,\"steps\":{...}}"),mapped=mapError(source);assert.equal(mapped.message,"POSTGRES_TRANSACTION_FAILED");assert(!mapped.message.includes("checkpoint_payload"));assert(!mapped.message.includes("version"))})
test("sanitização não aceita CAS_CONFLICT com detalhes do banco",()=>{const source=new Error("CAS_CONFLICT expected=5 actual=4 table=single_case_apply_checkpoints"),mapped=mapError(source);assert.equal(mapped.message,"POSTGRES_TRANSACTION_FAILED");assert(!mapped.message.includes("expected"));assert(!mapped.message.includes("actual"));assert(!mapped.message.includes("table"))})

test("sanitização preserva LEASE_OWNER_MISMATCH exato",()=>{const source=new Error("LEASE_OWNER_MISMATCH"),mapped=mapError(source);assert.equal(mapped.message,"LEASE_OWNER_MISMATCH");assert(mapped instanceof Error)})
