test("sanitização preserva LEASE_NOT_FOUND exato",()=>{const source=new Error("LEASE_NOT_FOUND"),mapped=mapError(source);assert.equal(mapped.message,"LEASE_NOT_FOUND");assert(mapped instanceof Error)})
