test("sanitização preserva INVALID_CHECKPOINT exato",()=>{const source=new Error("INVALID_CHECKPOINT"),mapped=mapError(source);assert.equal(mapped.message,"INVALID_CHECKPOINT");assert(mapped instanceof Error)})
test("sanitização preserva CHECKPOINT_BINDING_MISMATCH exato",()=>{const source=new Error("CHECKPOINT_BINDING_MISMATCH"),mapped=mapError(source);assert.equal(mapped.message,"CHECKPOINT_BINDING_MISMATCH");assert(mapped instanceof Error)})
test("sanitização preserva CAS_CONFLICT exato",()=>{const source=new Error("CAS_CONFLICT"),mapped=mapError(source);assert.equal(mapped.message,"CAS_CONFLICT");assert(mapped instanceof Error)})
test("sanitização preserva POSTGRES_UNAVAILABLE exato",()=>{const source=new Error("POSTGRES_UNAVAILABLE"),mapped=mapError(source);assert.equal(mapped.message,"POSTGRES_UNAVAILABLE");assert(mapped instanceof Error)})
test("sanitização preserva POSTGRES_TRANSACTION_FAILED exato",()=>{const source=new Error("POSTGRES_TRANSACTION_FAILED"),mapped=mapError(source);assert.equal(mapped.message,"POSTGRES_TRANSACTION_FAILED");assert(mapped instanceof Error)})
test("sanitização preserva SCHEMA_INCOMPATIBLE exato",()=>{const source=new Error("SCHEMA_INCOMPATIBLE"),mapped=mapError(source);assert.equal(mapped.message,"SCHEMA_INCOMPATIBLE");assert(mapped instanceof Error)})

test("sanitização sempre produz novo Error para código legítimo",()=>{const source=new Error("LEASE_EXPIRED");const mapped=mapError(source);assert.notStrictEqual(mapped,source);assert(mapped instanceof Error);assert.equal(mapped.message,"LEASE_EXPIRED")})
test("sanitização sempre produz novo Error para erro desconhecido",()=>{const source=new Error("UNKNOWN_ERROR_WITH_SECRET_DATA");const mapped=mapError(source);assert.notStrictEqual(mapped,source);assert(mapped instanceof Error);assert.equal(mapped.message,"POSTGRES_TRANSACTION_FAILED");assert(!mapped.message.includes("UNKNOWN"))})
test("sanitização mapeia POOL_UNAVAILABLE para POSTGRES_UNAVAILABLE",()=>{const source=new Error("POOL_UNAVAILABLE");const mapped=mapError(source);assert.equal(mapped.message,"POSTGRES_UNAVAILABLE")})
test("sanitização mapeia código ECONNREFUSED para POSTGRES_UNAVAILABLE",()=>{const source=Object.assign(new Error("connection refused"),{code:"ECONNREFUSED"});const mapped=mapError(source);assert.equal(mapped.message,"POSTGRES_UNAVAILABLE")})
test("sanitização mapeia ConnectionTerminatedError para POSTGRES_UNAVAILABLE",()=>{const source=Object.assign(new Error("connection terminated"),{name:"ConnectionTerminatedError"});const mapped=mapError(source);assert.equal(mapped.message,"POSTGRES_UNAVAILABLE")})

test("sanitização remove completamente stack trace do erro original",()=>{const source=Object.assign(new Error("POSTGRES_UNAVAILABLE secret-connection-string"),{stack:"at secret-place (file.js:123:456)"});const mapped=mapError(source);assert(!mapped.stack||!mapped.stack.includes("secret-place"));assert(!mapped.stack||!mapped.stack.includes("secret-connection"))})
test("sanitização não herda propriedades cause do erro original",()=>{const cause=new Error("ROOT_CAUSE_WITH_SECRETS");const source=Object.assign(new Error("FENCING_REJECTED"),{cause});const mapped=mapError(source);assert(!mapped.cause||!mapped.cause.message.includes("SECRETS"))})
